for a0 in 0..16:
    for a1 in 0..seq_len:
        for a2 in 0..seq_len:
            in0 = load scores[a0, a1, a2]
            acc0 <- maximum(acc0, in0) over a2
        for a2 in 0..seq_len:
            in1 = load scores[a0, a1, a2]
            v0 = subtract(in1, acc0)
            v1 = exp(v0)
            acc1 <- add(acc1, v1) over a2
        for a4 in 0..128:
            for a5 in 0..seq_len:
                in2 = load scores[a0, a1, a5]
                v2 = subtract(in2, acc0)
                v3 = exp(v2)
                v4 = divide(v3, acc1)
                in3 = load v[a0, a5, a4]
                f32 v5 = multiply(in3, v4)
                acc2 <- add(acc2, v5) over a5
            o[a0, a1, a4] = acc2
